    // `require` works for JSON files; you can also use `fs.readFileSync`
    users = require(process.env.USERS_FIXTURE);
  } catch (e) {
    console.warn('Failed to load USERS_FIXTURE, falling back to default demo users:', e);
  }
}

/* ---------- Simple API‑key auth (optional) ---------- */
function requireApiKey(req, res, next) {
  // If you set API_KEY env var, the route becomes protected; otherwise it stays open.
  const expected = process.env.API_KEY;
  if (!expected) return next(); // No API key required – useful for dev
  const provided = req.headers['x-api-key'];
  if (provided !== expected) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

/* ---------- Routes ---------- */
app.get('/health', (req, res) => {
  res.json({ status: HEALTH_STATUS, timestamp: new Date().toISOString() });
});

app.get('/users', requireApiKey, (req, res) => {
  // Example: strip emails for the public response unless you explicitly want them
  const hideEmail = process.env.HIDE_EMAILS === 'true';
  const result = hideEmail
    ? users.map(({ id, name }) => ({ id, name }))
    : users;
  res.json(result);
});

/* ---------- Central error handling ---------- */
app.use((err, _req, res, _next) => {
  console.error(err);
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;
  res.status(status).json({ error: message });
});

/* ---------- Server start ---------- */
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

