### How to refactor for environment‑driven configuration

Below is a minimal example showing how the hard‑coded values can be replaced by environment variables while preserving the simple demo nature of the app:

```js
// app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ---------- Security hardening ----------
app.use(helmet());
app.use(cors({
  // comma‑separated list in env, e.g. "https://myapp.com,https://admin.myapp.com"
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
}));
app.use(rateLimit({
  windowMs: 60_000, // 1 minute
  max: process.env.RATE_LIMIT_MAX ? parseInt(process.env.RATE_LIMIT_MAX, 10) : 100,
}));
app.use(morgan('combined'));
app.disable('x-powered-by');

// ---------- Configuration ----------
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

// ---------- Optional external data ----------
let USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com' },
];

// If a seed file is supplied (useful for CI or local dev), load it.
if (process.env.USER_SEED_PATH) {
  try {
    USERS = require(process.env.USER_SEED_PATH);
  } catch (e) {
    console.warn('Failed to load USER_SEED_PATH, falling back to built‑in list', e);
  }
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // If you ever want to hide the timestamp, guard it behind an env flag:
  const payload = { status: 'ok' };
  if (process.env.HEALTH_SHOW_TIMESTAMP === 'true') {
    payload.timestamp = new Date().toISOString();
  }
  res.json(payload);
});

app.get('/users', (req, res) => {
  // In a real app you’d protect this route with auth.
  res.json(USERS);
});

// ---------- Error handling ----------
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

// ---------- Server start ----------
if (require.main === module) {
  app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
}

module.exports = app;
```

**Key take‑aways**

1. **Port** → `process.env.PORT` (fallback to `3000` for local dev).  
2. **CORS whitelist, rate‑limit settings, health‑check details** → configurable via env vars.  
3. **User data** → load from an external JSON file whose path is supplied by `USER_SEED_PATH`.  
4. **Secrets** → never stored in source; keep them exclusively in environment variables or a secret manager, and ensure `.env*` files are ignored by version control.  
5. **Framework fingerprint** → disable the default `X‑Powered‑By` header.

Implementing these changes eliminates hard‑coded values, reduces the risk of accidental secret leakage, and makes the service flexible enough to run safely across multiple environments (dev, test, staging, production).

