```js
// app.js (updated)
require('dotenv').config();               // Load .env vars
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// -------------------- Middleware --------------------
app.use(helmet());                         // Security headers
app.use(cors({ origin: process.env.ALLOWED_ORIGIN || '*' })); // Adjust CORS as needed
app.use(express.json());                  // Body parser (if future routes need it)
app.use(morgan('combined'));              // Request logging

// Rate limiting – 100 req / 15 min per IP (tune as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// -------------------- Routes --------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Example: hide email in a public endpoint
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// -------------------- Error handling --------------------
app.use((err, req, res, next) => {
  // Log the error server‑side (could use a logger like Winston)
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// -------------------- Server start --------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### Next Steps

1. **Add a `package.json`** with proper version pinning and run `npm audit`.  
2. **Implement authentication** (e.g., JWT or session) for any route that will eventually serve sensitive data.  
3. **Deploy behind HTTPS** (terminate TLS at a reverse proxy or use `https.createServer`).  
4. **Set up CI/CD scanning** (e.g., `npm audit`, `snyk`, or `OWASP Dependency‑Check`).  
5. **Write integration tests** that assert security headers are present (`helmet`) and that rate limiting works.  

Addressing the points above will greatly reduce the attack surface of this simple Express app and bring it in line with common Node.js security best practices.

